// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    Log lg;

    function setUp() public { lg = new Log(); c = new W_WALLET(address(lg)); }

    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0));
        uint256 amt = bound(uint256(amount), 1, type(uint96).max);
        vm.deal(actor, amt);
        vm.prank(actor);
        c.Put{value: amt}(block.timestamp);
        (, , uint256 val, ) = lg.History(0);
        assertTrue(val == amt && val == __invmut_c_Acc_balance(actor));
    }

    function __invmut_c_Acc_balance(address __k) internal view returns (uint256) {
        (, uint256 _v1) = c.Acc(__k);
        return _v1;
    }
}
